// packages/core/src/agent_commands.ts
function buildAgentCommands(commandPrefix) {
  return [
    {
      name: "sync",
      purpose: "Compile memory, validate source files, and run health checks.",
      whenToUse: "Run before agent work or after checkout, merge, pull, or rebase.",
      examples: [`${commandPrefix} sync`]
    },
    {
      name: "context",
      purpose: "Retrieve task, changed-file, or diff-specific memory for agent work.",
      whenToUse: "Run before editing code so relevant claims, recipes, and verification steps are visible.",
      examples: [
        `${commandPrefix} context --task "fix student oauth"`,
        `${commandPrefix} context --changed-files src/auth.js`,
        `${commandPrefix} context --git-diff`,
        `${commandPrefix} context --format-version 2 --task "receipt retry" --budget medium --json`
      ]
    },
    {
      name: "coverage",
      purpose: "Check whether changed watched files have related memory updates or waivers.",
      whenToUse: "Run before finishing work, especially in CI or when watched files changed.",
      examples: [`${commandPrefix} coverage --git-diff`, `${commandPrefix} coverage --git-diff --base origin/main`]
    },
    {
      name: "audit",
      purpose: "Audit changed memory for deterministic stale-claim risks.",
      whenToUse: "Run before finishing when canonical memory files changed.",
      examples: [
        `${commandPrefix} audit --git-diff`,
        `${commandPrefix} audit --git-diff --base origin/main`,
        `${commandPrefix} audit --git-diff --strict`,
        `${commandPrefix} audit --format-version 2 --json`
      ]
    },
    {
      name: "categories",
      purpose: "List repository concern vocabulary, descriptions, and optional distinct eligible counts.",
      whenToUse: "Discover exact concern facets before v2 browse. OR within repeated system/status filters; AND across facets. Default statuses: current, proposed, needs_review.",
      examples: [`${commandPrefix} categories list --counts --json`, `${commandPrefix} categories list --system auth --status current --json`]
    },
    {
      name: "query",
      purpose: "Search compiled claims by topic.",
      whenToUse: "Use when you need memory about a behavior, subsystem, file, symbol, or route.",
      examples: [`${commandPrefix} query "student oauth tenant"`, `${commandPrefix} query --format-version 2 --system auth --json`, `${commandPrefix} query --format-version 2 --category security --tag concern:security --json`]
    },
    {
      name: "show",
      purpose: "Show one claim and optionally graph-related claims.",
      whenToUse: "Use when you need exact claim metadata, linked files, tags, or graph context.",
      examples: [`${commandPrefix} show auth.student_oauth.uid_is_tenant_scoped --include-related`, `${commandPrefix} show auth.student_oauth.uid_is_tenant_scoped --format-version 2 --json`]
    },
    {
      name: "system",
      purpose: "Summarize memory for one system.",
      whenToUse: "Use before editing a subsystem to inspect critical claims, recipes, watched files, and graph activity.",
      examples: [`${commandPrefix} system auth`]
    },
    {
      name: "recipes",
      purpose: "List, search, and show reusable workflow recipes.",
      whenToUse: "Use when you need a workflow package with required claims, steps, files, and verification.",
      examples: [`${commandPrefix} recipes search "student oauth"`, `${commandPrefix} recipes show recipe.auth.modify_student_oauth`]
    },
    {
      name: "plans",
      purpose: "Search plan templates and manage local generated plan runs.",
      whenToUse: "Use for multi-stage work where an agent should follow explicit stages, gather stage context, and close out local state.",
      examples: [
        `${commandPrefix} plans suggest --task "change student oauth provider"`,
        `${commandPrefix} plans new --template plan_template.auth.oauth_change --task "change student oauth provider"`,
        `${commandPrefix} context --plan plan_run.20260702.oauth_change.1234abcd --stage inspect`
      ]
    },
    {
      name: "profiles",
      purpose: "List, show, and match profile traits for task-specific context guidance.",
      whenToUse: "Use when you need explainable guidance for reviews, architecture work, implementation scope, releases, or migrations.",
      examples: [
        `${commandPrefix} profiles match --task "review auth changes"`,
        `${commandPrefix} profiles show profile_trait.review.findings_first`,
        `${commandPrefix} context --task "review auth changes" --profile review`
      ]
    },
    {
      name: "templates",
      purpose: "List and show claim templates.",
      whenToUse: "Use before creating claims so new memory follows the supported shape.",
      examples: [`${commandPrefix} templates list`, `${commandPrefix} templates show claim:fact`]
    },
    {
      name: "migrate-docs",
      purpose: "Plan or create proposed memory drafts from existing repository docs.",
      whenToUse: "Use when adopting agent-memory in a repo with existing documentation.",
      examples: [
        `${commandPrefix} migrate-docs --from docs/legacy --system auth`,
        `${commandPrefix} migrate-docs --from docs/legacy --system auth --automatic`
      ]
    },
    {
      name: "new claim",
      purpose: "Create one low-confidence atomic claim draft.",
      whenToUse: "Use when durable behavior, architecture, risk, decisions, or constraints changed and existing memory does not own it.",
      examples: [`${commandPrefix} new claim --type fact --system auth --title "Student OAuth UID is tenant scoped"`]
    },
    {
      name: "new recipe",
      purpose: "Create one first-class reusable workflow recipe draft.",
      whenToUse: "Use when future agents need repository-specific recurring steps, safeguards, and verification.",
      examples: [`${commandPrefix} new recipe --system auth --title "Modify OAuth safely" --source-file src/auth.js`]
    },
    {
      name: "validate",
      purpose: "Validate canonical memory files.",
      whenToUse: "Run before finishing changes to catch invalid claims, graphs, indexes, recipes, and waivers.",
      examples: [`${commandPrefix} validate`]
    },
    {
      name: "compile",
      purpose: "Build the repo-local SQLite cache from canonical memory.",
      whenToUse: "Run after changing canonical memory or before retrieval if the database is missing.",
      examples: [`${commandPrefix} compile`]
    },
    {
      name: "doctor",
      purpose: "Check whether the compiled database is present, fresh, and compatible.",
      whenToUse: "Run when retrieval fails or after repository state changes.",
      examples: [`${commandPrefix} doctor`]
    },
    {
      name: "upgrade",
      purpose: "Refresh generated support files or migrate local wrapper mode to global storage.",
      whenToUse: "Run after upgrading the package, or use --global for an explicit dry-run-first local-to-global migration.",
      examples: [`${commandPrefix} upgrade`, `${commandPrefix} upgrade --write`, `${commandPrefix} upgrade --adopt-retrieval --format-version 2 --json`, `${commandPrefix} upgrade --adopt-retrieval --format-version 2 --default-format-version 2 --json`, "agent-memory upgrade --global --write"]
    }
  ];
}
