function inspectRepositoryWrapper(repoRoot) {
  const wrapperPath = path18.join(repoRoot, "bin/memory");
  if (!fs16.existsSync(wrapperPath)) {
    return {
      path: wrapperPath,
      exists: false,
      isRegularFile: false,
      isReadable: false,
      isExecutable: false,
      isUsable: false
    };
  }
  let isRegularFile = false;
  try {
    isRegularFile = fs16.statSync(wrapperPath).isFile();
  } catch {
    return {
      path: wrapperPath,
      exists: true,
      isRegularFile: false,
      isReadable: false,
      isExecutable: false,
      isUsable: false
    };
  }
  if (!isRegularFile) {
    return {
      path: wrapperPath,
      exists: true,
      isRegularFile: false,
      isReadable: false,
      isExecutable: false,
      isUsable: false
    };
  }
  const isReadable = hasAccess(wrapperPath, fs16.constants.R_OK);
  const isExecutable = hasAccess(wrapperPath, fs16.constants.X_OK);
  return {
    path: wrapperPath,
    exists: true,
    isRegularFile: true,
    isReadable,
    isExecutable,
    isUsable: isReadable && isExecutable
  };
}
